import org.springframework.web.bind.annotation.ResponseBody;
import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdviceAdapter;

/**
 * Rejects creating an owner once 100 or more owners already share the request's effective
 * registration business day (by registrationDate), answering 429. Kept as its own advice so
 * this rule stays a small,
 * self-contained unit rather than growing the controller or another handler.
 */
@ControllerAdvice
@Order(Ordered.HIGHEST_PRECEDENCE)
public class OwnerDailyCreationLimitAdvice extends RequestBodyAdviceAdapter {

    private static final int DAILY_LIMIT = 100;

    private final ClinicService clinicService;

    public OwnerDailyCreationLimitAdvice(ClinicService clinicService) {
        this.clinicService = clinicService;
    }

    @Override
    public boolean supports(MethodParameter methodParameter, Type targetType,
                            Class<? extends HttpMessageConverter<?>> converterType) {
        Method method = methodParameter.getMethod();
        return OwnerFieldsDto.class.equals(targetType)
            && method != null && "addOwner".equals(method.getName());
    }

    @Override
    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
        LocalDate businessDay = RegistrationBusinessDay.effective(((OwnerFieldsDto) body).getRegistrationDate());
        long count = clinicService.findAllOwners().stream()
            .map(Owner::getRegistrationDate)
            .filter(businessDay::equals)
            .count();
        if (count >= DAILY_LIMIT) {
            throw new DailyLimitReachedException();
        }
        return body;
    }

    @ExceptionHandler(DailyLimitReachedException.class)
    @ResponseBody
    public ResponseEntity<String> handleDailyLimitReached(DailyLimitReachedException e) {
        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(e.getMessage());
    }

    /** Signals that the maximum number of owners for today has already been created. */
    static class DailyLimitReachedException extends RuntimeException {

        DailyLimitReachedException() {
            super("daily owner creation limit reached");
        }
    }
}

